    "C++/Clang++/Unsafe": "make -j unsafe",
    "C++/G++/Unsafe": "make -j unsafe",
    "C++/Clang++/PGO/Gen": "make -j pgo-clang-gen",
    "C++/Clang++/PGO": "make -j pgo-clang",
    "C++/G++/PGO/Gen": "make -j pgo-gcc-gen",
    "C++/G++/PGO": "make -j pgo-gcc",
    "Rust": "cargo build --release",
    "Rust/WMO": "cargo build --profile wmo",
    "Rust/WMO/Unchecked": "cargo build --profile no-checks",
    "Rust/MaxPerf/Unsafe": "cargo build --profile max-perf",
    "Rust/WASM/Node": "sh -c 'cargo build --target wasm32-wasip1 --release; wasm-opt -O3 target/wasm32-wasip1/release/benchmarks.wasm -o target/wasm32-wasip1/release/benchmarks-opt.wasm'",
    "Rust/WASM/Wasmtime": "sh -c 'cargo build --target wasm32-wasip1 --release; wasm-opt -O3 target/wasm32-wasip1/release/benchmarks.wasm -o target/wasm32-wasip1/release/benchmarks-opt.wasm'",
    "Rust/WASM/Wasmer": "sh -c 'cargo build --target wasm32-wasip1 --release; wasm-opt -O3 target/wasm32-wasip1/release/benchmarks.wasm -o target/wasm32-wasip1/release/benchmarks-opt.wasm'",
    "Rust/WASM/WasmEdge": "sh -c 'cargo build --target wasm32-wasip1 --release; wasm-opt -O3 target/wasm32-wasip1/release/benchmarks.wasm -o target/wasm32-wasip1/release/benchmarks-opt.wasm; wasmedge compile target/wasm32-wasip1/release/benchmarks-opt.wasm target/wasm32-wasip1/release/benchmarks-opt-aot.wasm'",
    "Rust/PGO/Gen": "sh -c '\n  RUSTFLAGS=\"-Cprofile-generate=target/pgo-data\" cargo build --release --target-dir=target/pgo-gen\n'",
    "Rust/PGO": "sh -c '\n  if [ ! -d \"target/pgo-data\" ] || [ -z \"$(ls -A target/pgo-data)\" ]; then\n    echo \"Error: No PGO data found. Run Rust/PGO/Gen first.\";\n    exit 1;\n  fi;\n  llvm-profdata merge -o target/pgo-data/merged.profdata target/pgo-data;\n  RUSTFLAGS=\"-Cprofile-use=/src/rust/target/pgo-data/merged.profdata -Cllvm-args=-pgo-warn-missing-function -Cllvm-args=--pgo-verify-bfi\" cargo build --release --target-dir=target/pgo-use\n'",
    "Zig": "zig build build-zig",
    "Zig/Unchecked": "zig build build-unchecked",
    "Crystal": "crystal build main.cr --release -o ./target/bin_crystal",
    "Crystal/O3": "crystal build main.cr -O3 -o ./target/bin_crystal_o3",
    "Mojo": "pixi run mojo build -O3 main.mojo -o target/bin_mojo",
    "D/DMD": "dub build --compiler=dmd -c release-dmd --build=release",
    "D/DMD/Perf": "dub build --compiler=dmd -c perf-dmd --build=release",
    "D/LDC": "dub build --compiler=ldc2 -c release-ldc --build=release",
    "D/LDC/Perf": "dub build --compiler=ldc2 -c perf-ldc --build=release",
    "D/LDC/MaxPerf": "dub build --compiler=ldc2 -c maxperf-ldc --build=release",
    "V/GCC": "v -enable-globals -cc gcc -prod -o target/v_gcc .",
    "V/GCC/Perf": "v -enable-globals -cc gcc -prod -cflags '-O3 -march=native -flto' -o target/v_gcc_perf .",
    "V/Clang": "v -enable-globals -cc clang -prod -o target/v_clang .",
    "V/Clang/Perf": "v -enable-globals -cc clang -prod -cflags '-O3 -march=native -flto' -o target/v_clang_perf .",
    "Go": "go build -buildvcs=false -o target/bin_go",
    "Go/Opt": "go build -buildvcs=false -a -trimpath -ldflags=\"-s -w -extldflags '-static'\" -tags=\"osusergo,netgo\" -o target/bin_go_opts",
    "C#/JIT": "dotnet build -c Release",
    "C#/AOT": "dotnet publish -c Release -p:PublishAOT=true -p:IlcOptimizationPreference=Speed -p:IlcInstructionSet=native -p:EnableCppCli=true -p:InvariantGlobalization=true -o ./bin/aot",
    "C#/SC-JIT": "dotnet publish -c Release --self-contained true --runtime ubuntu.26.04-x64 -p:PublishTrimmed=true -p:InvariantGlobalization=true -o ./bin/sc-jit",
    "C#/SC-AOT": "dotnet publish -c Release -p:PublishAOT=true --self-contained true --runtime linux-x64 -p:IlcOptimizationPreference=Speed -p:IlcInstructionSet=native -p:EnableCppCli=true -p:InvariantGlobalization=true -p:IlcGenerateStackTraceData=false -o ./bin/sc-aot",
    "C#/R2R": "dotnet publish -c Release -p:PublishReadyToRun=true -p:PublishTrimmed=true -p:InvariantGlobalization=true -o ./bin/r2r",
    "C#/AOT-EXTREME": "dotnet publish -c Release -p:PublishAOT=true -p:IlcOptimizationPreference=Speed -p:IlcInstructionSet=native -p:EnableCppCli=true -p:InvariantGlobalization=true -p:IlcGenerateStackTraceData=false -p:IlcFoldIdenticalMethodBodies=true -p:IlcGenerateCompleteTypeMetadata=false -p:IlcMethodBodyLayout=HotCold -p:IlcSingleMethodOptimization=aggressive -o ./bin/aot-extreme",
    "F#/JIT": "dotnet build -c Release",
